-- Bestiary: monsters generated by the Dungeon Master. Run once in the Supabase SQL editor.
-- Everyone logged in can read them (players need them to see enemies in a fight);
-- only the Dungeon Master can add, change or remove them.

create table public.monsters (
  id text primary key,
  data jsonb not null,
  created_at timestamptz not null default now()
);

alter table public.monsters enable row level security;

create policy "monsters: logged-in users can read" on public.monsters
  for select to authenticated using (true);
create policy "monsters: the DM manages" on public.monsters
  for all to authenticated using (public.is_dm()) with check (public.is_dm());

alter publication supabase_realtime add table public.monsters;
